INSERT INTO `services` (`id`, `user_id`, `title`, `description`, `category`, `price`, `availability`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(8, 7, 'Hand Embroidery Essentials', 'Basic stitches and pattern making for clothing or décor.', NULL, 83.00, '[{\"day\":\"Monday\",\"startTime\":\"15:51\",\"endTime\":\"17:51\"},{\"day\":\"Monday\",\"startTime\":\"18:59\",\"endTime\":\"22:59\"}]', 'active', '2025-09-30 15:59:40', '2025-12-04 07:11:30', '2025-12-04 07:11:30'),
(9, 7, 'Hand Lettering / Calligraphy', 'A creative skill focused on stylized writing using brush pens. Students learn stroke control, letter formation, and decorative styles for journaling, cards, or posters.ssss', NULL, 10.00, '[{\"day\":\"Monday\",\"startTime\":\"14:53\",\"endTime\":\"17:54\"},{\"day\":\"Wednesday\",\"startTime\":\"14:56\",\"endTime\":\"17:54\"},{\"day\":\"Friday\",\"startTime\":\"11:43\",\"endTime\":\"02:44\"}]', 'active', '2025-10-01 04:50:47', '2025-12-04 07:17:55', '2025-12-04 07:17:55'),
(11, 5, 'Resin Art', 'Crafting decorative items using epoxy resin. This includes mixing resin, adding pigments or glitters, and creating coasters, keychains, bookmarks, or jewelry.', NULL, 30.00, '[{\"day\":\"Tuesday\",\"startTime\":\"12:57\",\"endTime\":\"16:57\"}]', 'active', '2025-10-28 01:48:30', '2025-12-04 11:31:14', NULL),
(16, 9, 'Embroidery', 'Decorating fabric using needle and thread. This includes basic stitches, pattern tracing, and making hoop art, patches, or fabric embellishments.\n\n4. Calligraphy', NULL, 16.00, '[{\"day\":\"Monday\",\"startTime\":\"12:21\",\"endTime\":\"14:23\"},{\"day\":\"Wednesday\",\"startTime\":\"15:22\",\"endTime\":\"17:22\"},{\"day\":\"Friday\",\"startTime\":\"01:42\",\"endTime\":\"03:42\"}]', 'active', '2025-12-02 00:21:58', '2025-12-04 18:14:34', NULL),
(20, 9, 'Knitting', 'Using two needles to create fabric from yarn. Skills include casting on, knitting, purling, and making simple scarves, headbands, or small wearables.', NULL, 10.00, '[{\"day\":\"Monday\",\"startTime\":\"19:44\",\"endTime\":\"22:43\"}]', 'Active', '2025-12-04 06:43:49', '2025-12-04 18:14:15', NULL),
(21, 7, 'Watercolor Painting', 'Creating soft and expressive artworks using water-based paints. This includes blending techniques, brush control, and simple landscape or floral painting.', NULL, 10.00, '[{\"day\":\"Monday\",\"startTime\":\"19:27\",\"endTime\":\"23:27\"}]', 'Active', '2025-12-04 07:27:59', '2025-12-04 18:16:08', NULL),
(22, 9, 'Crochet', 'Creating handmade items using yarn and a crochet hook. This includes learning basic stitches, reading patterns, and making accessories like coasters, bags, or amigurumi.', NULL, 10.00, '[{\"day\":\"Monday\",\"startTime\":\"22:00\",\"endTime\":\"22:02\"}]', 'Active', '2025-12-04 09:00:24', '2025-12-04 18:14:00', NULL),
(23, 7, 'Calligraphy', 'Writing decorative lettering using brush pens or calligraphy pens. This includes stroke practice, alphabet styles, and creating cards or themed quotes.', NULL, 10.00, '[{\"day\":\"Saturday\",\"startTime\":\"13:49\",\"endTime\":\"15:49\"}]', 'Active', '2025-12-04 09:49:35', '2025-12-04 18:15:57', NULL),
(24, 9, 'Journaling & Scrapbooking', 'Crafting personalized journal or scrapbook pages using pens, stickers, photos, and decorations. This includes layout design, theme planning, and creative storytelling.', NULL, 19.00, '[{\"day\":\"Monday\",\"startTime\":\"10:08\",\"endTime\":\"10:13\"}]', 'Active', '2025-12-06 21:09:00', '2025-12-06 21:09:00', NULL),
